ruleSearch.bookList:
.l-m1
<js>
/*
 * 禁忌书屋(cool18 bbs4) 搜索列表聚合脚本
 * 把搜索结果里的书贴按【书名】聚合成"书", 供阅读(Legado)搜索列表显示
 * 参考旧书源 by河鹅和 的写法改写, 适配 cool18 新版 wap 模板
 *
 * 两个坑:
 * 1) 搜索结果里"主贴"的标题是加粗的(<b>), 后面更新的章节经常以"跟帖"发出, 标题不加粗,
 *    所以不能只看加粗的, 也不能用 first=1 过滤(那样会把新章节全丢掉);
 * 2) 同一本书的标题写法不统一, 有【仙宫香妃录】、《仙宫香妃录》、【仙宫香妃录(新版)】等,
 *    要按"去掉书名号+统一括号"后的书名聚合, 才不会一本书拆成好几本
 */
var keyList = [];
var bookList = [];
try {
    var rawVar = source.getVariable();
    if (rawVar) {
        var Variable = JSON.parse(rawVar);
        if (Variable) {
            if (Variable.keyList) keyList = Variable.keyList;
            if (Variable.bookList) bookList = Variable.bookList;
        }
    }
} catch (e) {
    keyList = [];
    bookList = [];
}

function trimStr(s) {
    if (s === null || typeof s == "undefined") return "";
    return String(s).replace(/^\s+|\s+$/g, "");
}

function listCount(list) {
    if (!list) return 0;
    if (typeof list.length == "number") return list.length;
    return list.size();
}

function listItem(list, i) {
    var v = null;
    try { v = list[i]; } catch (e1) { v = null; }
    if (v === null || typeof v == "undefined") {
        try { v = list.get(i); } catch (e2) { v = null; }
    }
    return v;
}

/* 取标题里第一对书名号(含括号), 没有则返回空 */
function pickRawName(title) {
    var opens = ["【", "《", "[", "［", "〔", "〖"];
    var closes = ["】", "》", "]", "］", "〕", "〗"];
    for (var i = 0; i < opens.length; i++) {
        var s = title.indexOf(opens[i]);
        if (s < 0) continue;
        var e = title.indexOf(closes[i], s + 1);
        if (e > s) return trimStr(title.substring(s, e + 1));
    }
    return "";
}

/* 显示用书名: 去掉两端的书名号 */
function displayName(raw) {
    var s = trimStr(raw);
    while (s.length > 0 && "【《[［〔〖".indexOf(s.charAt(0)) >= 0) s = s.substring(1);
    while (s.length > 0 && "】》]］〕〗".indexOf(s.charAt(s.length - 1)) >= 0) {
        s = s.substring(0, s.length - 1);
    }
    return trimStr(s);
}

/* 聚合用的键: 去掉所有书名号/空格, 全角括号转半角, 这样同一本书的不同写法会并成一本 */
function bookKey(name) {
    var out = "";
    var drop = "【】《》[]［］〔〕〖〗 \u3000\t\r\n";
    for (var i = 0; i < name.length; i++) {
        var ch = name.charAt(i);
        if (drop.indexOf(ch) >= 0) continue;
        if (ch === "（") out += "(";
        else if (ch === "）") out += ")";
        else out += ch;
    }
    return out;
}

/* 放进 URL 参数里用的键(只要不影响 URL 结构即可, 中文由阅读自己转义) */
function urlEscape(s) {
    var out = "";
    for (var i = 0; i < s.length; i++) {
        var ch = s.charAt(i);
        if (ch === "%") out += "%25";
        else if (ch === "&") out += "%26";
        else if (ch === "#") out += "%23";
        else if (ch === "+") out += "%2B";
        else if (ch === "=") out += "%3D";
        else if (ch === "?") out += "%3F";
        else out += ch;
    }
    return out;
}

/*
 * 目录页(按书名再搜一次)的关键词:
 * 实测本站搜索"多一个字、带空格或括号"就经常 0 结果, 含"乱伦"会被站点过滤,
 * 所以把书名切成片段, 取最长的安全片段(最多7字)当关键词, 目录页再用书名精确过滤
 */
function pickKeyword(key) {
    var s = trimStr(key);
    var chunks = s.split("乱伦");
    var best = "";
    for (var i = 0; i < chunks.length; i++) {
        var segs = chunks[i].split(/[^\u4e00-\u9fa5A-Za-z0-9]+/);
        for (var j = 0; j < segs.length; j++) {
            var seg = trimStr(segs[j]);
            if (seg.length > best.length) best = seg;
        }
    }
    if (best.length > 7) best = best.substring(0, 7);
    if (best.length < 2) best = s;
    if (best.length > 7) best = best.substring(0, 7);
    return best;
}

/* 从标题里取作者, 用字符串查找而不用正则(部分正则在 Rhino 里编译不过) */
function pickAuthor(title) {
    var tags = ["作者：", "作者:", "作者 :", "作：", "作:", "作 :"];
    var stops = [" ", "\u3000", "\t", "，", "。", "、", "）", ")", "】", "]", "（", "(", "【", "["];
    for (var i = 0; i < tags.length; i++) {
        var p = title.indexOf(tags[i]);
        if (p < 0) continue;
        var rest = title.substring(p + tags[i].length);
        var end = -1;
        for (var j = 0; j < stops.length; j++) {
            var k = rest.indexOf(stops[j]);
            if (k >= 0 && (end < 0 || k < end)) end = k;
        }
        if (end >= 0) rest = rest.substring(0, end);
        return trimStr(rest);
    }
    return "";
}

var count = listCount(result);
if (count === 0) {
    result = "[]";
} else {
    for (var i = 0; i < count; i++) {
        var b = listItem(result, i);
        if (!b) continue;
        var title = trimStr(java.getString("a@text", b));
        if (title === "") continue;
        var rawName = pickRawName(title);
        if (rawName === "") {
            /* 没书名号的: 只有主贴(标题加粗)才当成一本书, 跟帖直接丢掉, 免得生成垃圾书 */
            var boldTitle = trimStr(java.getString("a b@text", b));
            if (boldTitle === "") continue;
            rawName = title;
        }
        var bookname = displayName(rawName);
        var bookkey = bookKey(rawName);
        if (bookname === "" || bookkey === "") continue;
        var uploader = trimStr(java.getString("font@text", b));
        var date = trimStr(java.getString("i@text", b));
        var author = pickAuthor(title);
        var idx = keyList.indexOf(bookkey);
        if (idx === -1) {
            keyList.push(bookkey);
            bookList.push({
                bookname: bookname,
                key: urlEscape(bookkey),
                keyword: pickKeyword(bookkey),
                author: author,
                uploader: uploader,
                time: date,
                sum: 1
            });
        } else {
            bookList[idx].sum = bookList[idx].sum + 1;
        }
    }
    source.setVariable(JSON.stringify({ keyList: keyList, bookList: bookList }));
    result = JSON.stringify(bookList);
}
</js>
$[*]

ruleToc.chapterList:
