<js>
/*
 * 目录列表: 用"书名键"过滤搜索结果, 只留下这本书的书贴(主贴+跟帖都算, 更新章节常在跟帖里)
 * 过滤是精确匹配(把标题里的书名按同样的规则归一化后比较), 所以【仙宫香妃录】不会串到
 * 【仙宫香妃录（新版）】里; 万一一条都匹配不上, 再逐级放宽, 保证目录不为空
 */
var tocHitList = [];
var tocSoftList = [];
var tocAllList = [];

function tocTrim(s) {
    if (s === null || typeof s == "undefined") return "";
    return String(s).replace(/^\s+|\s+$/g, "");
}

/* 与搜索列表完全一致的书名归一化规则 */
function tocPickRawName(title) {
    var opens = ["【", "《", "[", "［", "〔", "〖"];
    var closes = ["】", "》", "]", "］", "〕", "〗"];
    for (var i = 0; i < opens.length; i++) {
        var s = title.indexOf(opens[i]);
        if (s < 0) continue;
        var e = title.indexOf(closes[i], s + 1);
        if (e > s) return tocTrim(title.substring(s, e + 1));
    }
    return "";
}

function tocBookKey(name) {
    var out = "";
    var drop = "【】《》[]［］〔〕〖〗 \u3000\t\r\n";
    for (var i = 0; i < name.length; i++) {
        var ch = name.charAt(i);
        if (drop.indexOf(ch) >= 0) continue;
        if (ch === "（") out += "(";
        else if (ch === "）") out += ")";
        else out += ch;
    }
    return out;
}

var tocWant = "";
try {
    tocWant = tocBookKey(tocTrim(book.name));
} catch (e) {
    tocWant = "";
}

var tocCount = 0;
if (result) {
    tocCount = (typeof result.length == "number") ? result.length : result.size();
}
for (var i = 0; i < tocCount; i++) {
    var tocEl = null;
    try { tocEl = result[i]; } catch (e1) { tocEl = null; }
    if (tocEl === null || typeof tocEl == "undefined") {
        try { tocEl = result.get(i); } catch (e2) { tocEl = null; }
    }
    if (!tocEl) continue;
    var tocName = tocTrim(java.getString("a@text", tocEl));
    var tocUrl = tocTrim(java.getString("a@href", tocEl));
    if (tocName === "" || tocUrl === "") continue;
    var tocItem = { name: tocName, url: tocUrl };
    tocAllList.push(tocItem);
    var tocRaw = tocPickRawName(tocName);
    var tocKey = tocBookKey(tocRaw === "" ? tocName : tocRaw);
    if (tocWant !== "" && tocKey === tocWant) {
        tocHitList.push(tocItem);
    } else if (tocWant !== "" && tocKey.indexOf(tocWant) >= 0) {
        tocSoftList.push(tocItem);
    }
}

if (tocHitList.length > 0) {
    result = JSON.stringify(tocHitList);
} else if (tocSoftList.length > 0) {
    result = JSON.stringify(tocSoftList);
} else {
    result = JSON.stringify(tocAllList);
}
</js>
